1	import { animate, stagger } from "motion";
2	
3	export function prefersReducedMotion() {
4	  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
5	}
6	
7	export function runFadeUpStagger(selector = "[data-animate]") {
8	  const elements = document.querySelectorAll<HTMLElement>(selector);
9	  if (elements.length === 0) return;
10	
11	  if (prefersReducedMotion()) {
12	    elements.forEach((el) => {
13	      el.style.opacity = "1";
14	    });
15	    return;
16	  }
17	
18	  animate(
19	    elements,
20	    { opacity: [0, 1], y: [16, 0] },
21	    { duration: 0.5, delay: stagger(0.06), ease: [0.22, 1, 0.36, 1] },
22	  );
23	}
24	
25	// Triggers the "Approach" section's grid background (see
26	// .ping-section--approach::before in ProjectLayout.astro) once the section
27	// scrolls into view, by adding a .grid-active class the CSS keyframe
28	// (gridSequence, in global.css) is keyed off of.
29	export function observeGridReveal(selector = ".ping-section--approach") {
30	  const elements = document.querySelectorAll<HTMLElement>(selector);
31	  if (elements.length === 0) return;
32	
33	  if (prefersReducedMotion()) {
34	    elements.forEach((el) => {
35	      el.classList.add("grid-active");
36	    });
37	    return;
38	  }
39	
40	  const observer = new IntersectionObserver(
41	    (entries, obs) => {
42	      for (const entry of entries) {
43	        if (!entry.isIntersecting) continue;
44	        entry.target.classList.add("grid-active");
45	        // Fire once per page view — don't replay the fade if the reader
46	        // scrolls back past this section again.
47	        obs.unobserve(entry.target);
48	      }
49	    },
50	    { threshold: 0.2 },
51	  );
52	
53	  elements.forEach((el) => observer.observe(el));
54	}
